SELECT ?composer ?composerLabelEn ?composerLabelRu ?label ?labelLabelEn ?labelLabelRu ?period_start ?gold_count_estimate WHERE {
      {
        SELECT ?composer ?composerLabelEn ?composerLabelRu ?label ?labelLabelEn ?labelLabelRu ?period_start (COUNT(DISTINCT ?item) AS ?gold_count_estimate) WHERE {
        ?item wdt:P31 wd:Q134556 .
        ?item wdt:P577 ?date .
        BIND(YEAR(?date) AS ?year) .
        FILTER(?year >= 1950 && ?year <= 2025) .
        ?item wdt:P658 ?track .
        ?track wdt:P86 ?composer .
        ?item wdt:P264 ?label .
        ?composer rdfs:label ?composerLabelEn FILTER(LANG(?composerLabelEn) = "en") .
        OPTIONAL { ?composer rdfs:label ?composerLabelRu FILTER(LANG(?composerLabelRu) = "ru") . }
        ?label rdfs:label ?labelLabelEn FILTER(LANG(?labelLabelEn) = "en") .
        OPTIONAL { ?label rdfs:label ?labelLabelRu FILTER(LANG(?labelLabelRu) = "ru") . }
        BIND((FLOOR((?year - 1950) / 15) * 15 + 1950) AS ?period_start) .
        }
        GROUP BY ?composer ?composerLabelEn ?composerLabelRu ?label ?labelLabelEn ?labelLabelRu ?period_start
      }
      FILTER(?gold_count_estimate >= 5 && ?gold_count_estimate <= 180)
    }
    ORDER BY DESC(?gold_count_estimate)
    LIMIT 800

